<script setup lang="ts">
import { type PropType } from 'vue';
import { Agent, Message } from '../../../types';
import StatusInfo from '../planning/StatusInfo.vue';
import ApprovalInfo from '../planning/ApprovalInfo.vue';
import MessageComponent from '../index.vue';

const props = defineProps({
  message: {
    type:    Object as PropType<Message>,
    default: () => ({} as Message),
  },
  agents: {
    type:     Array as PropType<Agent[]>,
    default:  () => [],
  },
  disabled: {
    type:    Boolean,
    default: false,
  },
  pendingConfirmation: {
    type:    Boolean,
    default: false,
  }
});

const emit = defineEmits(['update:message', 'confirm:message', 'send:message', 'stop:message', 'collapse']);

function handleCollapse(isCollapsed: boolean) {
  emit('collapse');
  emit('update:message', {
    ...props.message,
    planningContent: {
      ...props.message.planningContent,
      isCollapsed
    }
  });
}

</script>

<template>
  <div
    v-if="props.message?.planningContent"
    v-bind="$attrs"
    class="chat-planning-message"
  >
    <StatusInfo
      :value="props.message.planningContent"
      :agents="props.agents"
      :disabled="props.disabled"
      @confirm="emit('confirm:message', { result: $event })"
      @stop="emit('stop:message')"
      @collapse="handleCollapse"
    />
    <ApprovalInfo
      v-if="props.message.planningContent.approval"
      :principal="props.message?.templateContent?.content.principal"
      :disabled="props.disabled"
      :timestamp="props.message.timestamp"
    />
    <MessageComponent
      v-else
      :message="props.message"
      :disabled="props.disabled"
      :pending-confirmation="props.pendingConfirmation"
      @update:message="emit('update:message', $event)"
      @confirm:message="emit('confirm:message', $event)"
      @send:message="emit('send:message', $event)"
    />
  </div>
</template>

<style lang="scss">
  .chat-planning-message {
    display: contents;
  }
</style>
